mapper.select:
select p.purchaseid as purchaseid, p.productid as productid, p.codebid as codebid, p.createdat as createdat, p.quantity as quantity, p.notes as notes from purchase p where p.productid = #{productId}
and p.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')
and p.createdat <= str_to_date(#{endDate}, '%Y-%m-%d') + 0.99999
order by createdat desc, purchaseid desc limit #{size} offset #{offset}

select count(*) from purchase p where p.productid = #{productId}
and p.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')
and p.createdat <= str_to_date(#{endDate}, '%Y-%m-%d') + 0.99999

select t.adjustmentid as adjustmentid, t.productid as productid, t.codebid as codebid, t.createdat as createdat, t.quantity as quantity, t.notes as notes from ( select sa.adjustmentid as adjustmentid, sa.productid as productid, sa.codebid as codebid, sa.createdat as createdat, sa.quantity as quantity, sa.notes as notes from stockadjustment sa where sa.productid = #{productId}
and sa.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')
and sa.createdat <= str_to_date(#{endDate}, '%Y-%m-%d') + 0.99999
union all
select si.itemsalesid as adjustmentid, si.productid as productid, 'SALES' as codebid, si.createdat as createdat, si.quantity as quantity, '상품 판매' as notes from sales_item si where si.productid = #{productId}
and si.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')
and si.createdat <= str_to_date(#{endDate}, '%Y-%m-%d') + 0.99999
and si.status = 'ACTIVE' ) t order by createdat desc, adjustmentid desc limit #{size} offset #{offset}

	    select count(*)
	    from (
	        select adjustmentid from stockadjustment sa where sa.productid = #{productId}

				and sa.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')


				and sa.createdat <= str_to_date(#{endDate}, '%Y-%m-%d') + 0.99999

	        union all
	        select itemsalesid from sales_item si where si.productid = #{productId}

				and si.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')


				and si.createdat <= str_to_date(#{endDate}, '%Y-%m-%d') + 0.99999

            and si.status = 'ACTIVE'
	    ) as t

select p.productid as productid, p.name as productname, ifnull(pi.total_in, 0) as totalinbound, ifnull(sa.total_out, 0) as totaloutbound, ifnull(si.total_sales, 0) as totalsales, ifnull(pi.total_in,0) - ifnull(sa.total_out,0) - ifnull(si.total_sales,0) as currentstock from product p left join ( select productid, sum(quantity) as total_in from purchase group by productid ) pi on pi.productid = p.productid left join ( select productid, sum(quantity) as total_out from stockadjustment group by productid ) sa on sa.productid = p.productid left join ( select productid, sum(quantity) as total_sales from sales_item where status = 'ACTIVE' group by productid ) si on si.productid = p.productid
(lower(p.name) like concat('%', lower(#{keyword}), '%') or lower(p.codebid) like concat('%', lower(#{keyword}), '%'))
order by productname asc limit #{size} offset #{offset}
